// ── Helpers ──────────────────────────────────────────────────────────────────
inline bool frpgRegionsAdjacent(uint8_t a, uint8_t b) {
    if (a == REGION_UNKNOWN || b == REGION_UNKNOWN) return false;
    if (a == b) return true;
    if (a >= REGION_COUNT || b >= REGION_COUNT) return false;
    for (int i = 0; i < 8; i++) {
        if (FRPG_REGION_ADJ[a][i] == 0xFF) break;
        if (FRPG_REGION_ADJ[a][i] == b) return true;
    }
    return false;
}

inline const char* frpgRegionName(uint8_t regionId) {
    if (regionId >= REGION_COUNT) return "Wasteland";
    return FRPG_REGION_NAMES[regionId];
}
